"use client";
import {
  Bar,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { formatNumber, useChartHover } from "./chart-card";
import { ChartActiveDot } from "./chart-active-dot";
import { COMBO_DEMO_RANGES } from "./chart-demo-data";
import {
  average,
  type ChartCommonProps,
  ChartFrame,
  type ChartRange,
  chartAxis,
  ink,
  numeric,
  PeriodSelect,
  StatTiles,
  shortNumber,
  sum,
  useChartRange,
} from "./pro-chart";
export interface ComboPoint {
  label: string;
  [key: string]: string | number;
}
export interface ComboSeries {
  /** Optional inspected line/dot paint, independently of the legend colour. */
  activeColor?: string;
  key: string;
  label: string;
  color?: string;
  format?: (value: number) => string;
}
export interface ComboChartRange extends ChartRange {
  data: ComboPoint[];
}
export interface ComboChartCardProps extends ChartCommonProps {
  data?: ComboPoint[];
  bar?: ComboSeries;
  line?: ComboSeries;
  ranges?: ComboChartRange[];
  tiles?: boolean;
}
export const COMBO_DATA: ComboPoint[] = COMBO_DEMO_RANGES[0]!.data;
const RANGES: ComboChartRange[] = COMBO_DEMO_RANGES;

const BAR = { key: "sessions", label: "Sessions" },
  LINE = {
    key: "rate",
    label: "Conversion",
    format: (n: number) => `${+n.toFixed(1)}%`,
  };
export function ComboChartCard({
  data,
  bar = BAR,
  line = LINE,
  ranges: supplied,
  title = "Sessions",
  tiles = true,
  ...props
}: ComboChartCardProps = {}) {
  const ranges = supplied ?? (data ? undefined : RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    points = period.current?.data ?? data ?? COMBO_DATA,
    hover = useChartHover(),
    reduced = useHydratedReducedMotion();
  const point = hover.activeIndex != null ? points[hover.activeIndex] : undefined,
    total = sum(points.map((p) => numeric(p[bar.key]))),
    mean = average(points.map((p) => numeric(p[line.key]))),
    barFormat = bar.format ?? props.format ?? formatNumber,
    lineFormat = line.format ?? shortNumber,
    barColor = bar.color ?? ink(0),
    lineColor = line.color ?? ink(1);
  return (
    <ChartFrame
      title={`${point?.label ?? title} · ${line.label} ${lineFormat(point ? numeric(point[line.key]) : mean)}`}
      value={
        point ? numeric(point[bar.key]) : (period.current?.headline ?? props.headline ?? total)
      }
      format={barFormat}
      delta={point ? undefined : (period.current?.delta ?? props.delta)}
      animateNumber
      pulseKey={hover.activeIndex}
      className={props.className}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            hover.clear();
            period.select(id);
          }}
          label={period.current?.label ?? props.range}
        />
      }
      footer={
        tiles && (
          <StatTiles
            items={[
              {
                label: `${bar.label} · total`,
                value: barFormat(point ? numeric(point[bar.key]) : total),
                color: barColor,
              },
              {
                label: `${line.label} · ${point ? "this month" : "average"}`,
                value: lineFormat(point ? numeric(point[line.key]) : mean),
                color: lineColor,
              },
            ]}
            responsive
            balanceLastRow
          />
        )
      }
    >
      <div className="h-[196px] w-full">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart
            data={points}
            margin={{ top: 4, right: 0, bottom: 0, left: 0 }}
            barCategoryGap="22%"
            {...hover.handlers}
          >
            <CartesianGrid
              vertical={false}
              stroke="var(--color-chart-track)"
              strokeDasharray="4 4"
            />
            <XAxis
              {...chartAxis}
              dataKey="label"
              interval="preserveStartEnd"
              tick={{ ...chartAxis.tick, fontSize: 13 }}
              tickMargin={12}
            />
            <YAxis
              {...chartAxis}
              yAxisId="bar"
              width={44}
              tickCount={4}
              tickFormatter={shortNumber}
            />
            <YAxis
              {...chartAxis}
              yAxisId="line"
              orientation="right"
              width={40}
              tickCount={4}
              tickFormatter={lineFormat}
            />
            <Tooltip content={() => null} cursor={false} />
            <Bar
              yAxisId="bar"
              dataKey={bar.key}
              name={bar.label}
              fill={barColor}
              radius={8}
              maxBarSize={34}
              isAnimationActive={!reduced}
              animationDuration={450}
              animationEasing="ease"
            >
              {points.map((p, i) => (
                <Cell
                  key={p.label}
                  fill={
                    hover.activeIndex === i && !bar.color
                      ? barColor.replace(")", "-active)")
                      : barColor
                  }
                  opacity={hover.activeIndex != null && hover.activeIndex !== i ? 0.3 : 1}
                  className="transition-[fill,opacity] duration-200 ease-out"
                />
              ))}
            </Bar>
            <Line
              yAxisId="line"
              type="monotone"
              dataKey={line.key}
              stroke="var(--color-background-secondary-default)"
              strokeWidth={7}
              strokeLinecap="round"
              strokeLinejoin="round"
              dot={false}
              activeDot={false}
              isAnimationActive={!reduced}
              animationDuration={450}
              animationEasing="ease"
            />
            <Line
              yAxisId="line"
              type="monotone"
              dataKey={line.key}
              name={line.label}
              stroke={line.activeColor ?? line.color ?? lineColor.replace(")", "-active)")}
              strokeWidth={2}
              strokeLinecap="round"
              strokeLinejoin="round"
              dot={{
                r: 3,
                stroke: "var(--color-background-secondary-default)",
                strokeWidth: 2,
                fill: line.activeColor ?? line.color ?? lineColor.replace(")", "-active)"),
              }}
              activeDot={<ChartActiveDot />}
              isAnimationActive={!reduced}
              animationDuration={450}
              animationEasing="ease"
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </ChartFrame>
  );
}
